// === Tab: mySketch ===
const text = "Let the\ngames begin!",
			num = 5000;

let poss = [], vels = [], targets = [];

function setup() {
	createCanvas(Math.min(windowWidth, 1000), Math.min(windowHeight, 700));
	colorMode(HSB);
	let graphics = createGraphics(width, height);
	graphics.pixelDensity(1);
	graphics.textFont("Georgia");
	graphics.textAlign(CENTER);
	graphics.textSize(120);
	graphics.noStroke();
	graphics.fill(255);

	graphics.background(0);
	graphics.text(text, width / 2, height / 4);

	graphics.fill(255, 100, 50);
	graphics.loadPixels();

	let j = 0,
			p = graphics.pixels.filter((_, i) => i % 4 === 0),
			spacing = p.filter(x => x).length / num;
	for (let i = 0; i < p.length; i++) {
		if (p[i] !== 0) {
			j = (j + 0.5 + Math.random()) % spacing;
			if (Math.floor(j) === 0) {
				poss.push(new p5.Vector(random(width), random(height)));
				vels.push(p5.Vector.random2D());
				targets.push(new p5.Vector(i % width, Math.floor(i / height)));
			}
		}
	}

	stroke(255);
}

function draw() {
	background(0, 10);
	poss.forEach(function(pos, i) {
		let vel = vels[i],
				dir = p5.Vector.sub(targets[i], pos).normalize();
		vel.add(dir);
		vel.mult(0.9);
		pos.add(vel);
		stroke(i/5000*360,55,255);
		point(pos.x, pos.y);
		point(pos.x+1, pos.y);
		point(pos.x, pos.y+1);
		point(pos.x+1, pos.y+1);

	});
}

